
const DATA={"modules":[{"id":"m1","num":"01","title":"Electrical Architecture & Operational Boundaries","duration":"6–8 hours structured learning + practical site exposure","preamble":"Mission-critical electrical systems become manageable when the candidate can reconstruct them from first principles. This module develops a disciplined method for understanding complete power architecture without relying on memorising a finished SLD.","aim":"Develop the candidate’s ability to interpret, reconstruct and explain mission-critical electrical architecture and the operational boundaries that govern it.","objectives":["Trace energy from incoming HV supply through transformation and LV distribution.","Distinguish normal, resilient and alternative electrical paths.","Recognise operational boundaries between systems, equipment and responsible persons.","Use progressive overlays to turn complex SLDs into understandable system models."],"outcomes":["Explain a complete generic HV-to-LV architecture in logical stages.","Identify normal and alternative sources feeding a selected load.","Produce a simplified system drawing that accurately represents energy paths.","Identify information that remains unknown rather than making assumptions."],"sections":[["1.1","Why Architecture Comes First","Complex data-centre SLDs contain more information than a new candidate can absorb in one pass. The programme therefore begins by separating the system into functional layers, understanding each layer, and then rebuilding the complete architecture.","Break a generic system into source, transformation, distribution, resilience and load layers."],["1.2","Incoming HV and Distribution","Understand the role of incoming utility or private-network supplies, HV switchgear, sectionalisation and the relationship between source availability and downstream resilience.","Trace a generic incoming HV source to its transformer interface."],["1.3","Transformer Interfaces","Examine the electrical and operational boundary between HV distribution, transformers and LV switchboards, including why isolation on one side cannot be considered without the other.","Identify upstream and downstream dependencies around a transformer."],["1.4","Fundamental LV Distribution","Build the basic path from transformer to LV main switchboard and principal distribution before adding resilience or UPS complexity.","Create a simplified transformer-to-LV-board sketch."],["1.5","A/B Resilient Architecture","Understand why mission-critical loads are commonly provided with diverse power paths and why redundancy does not mean the two paths are operationally independent in every condition.","Compare normal and degraded A/B states."],["1.6","Bus Sections, Couplers and Interconnections","Explore how bus section arrangements and couplers can alter the sources capable of energising equipment.","Identify how an open or closed coupler changes possible energisation paths."],["1.7","Operational Boundaries","Understand the importance of defining which person, rule set, system or operational authority controls each part of the electrical network.","Write a boundary statement for a fictional system."],["1.8","SLD Interpretation Discipline","Develop a repeatable process for reading SLDs: establish scope, identify sources, follow normal paths, identify alternate paths, identify stored energy, then test assumptions.","Apply the process to a simplified diagram."],["1.9","Architecture Reconstruction","Move from reading a supplied drawing to producing a candidate-generated simplified architecture, demonstrating genuine comprehension rather than visual recognition.","Produce and explain a simplified system reconstruction."],["1.10","Module Integration Exercise","Consolidate the module by explaining a generic mission-critical architecture from source to critical load, including at least one alternate supply route.","Complete the architecture explanation and self-check."]]},{"id":"m2","num":"02","title":"Safety Rules, Roles & Safety Documentation","duration":"5–7 hours structured learning + organisation-specific rule study","preamble":"Experienced SAPs normally arrive with a strong safety-rule foundation. The development requirement is not to discard that discipline, but to apply it correctly within systems containing alternative supplies, stored energy and operational states that may differ from conventional distribution networks.","aim":"Translate established electrical-safety discipline into the mission-critical environment while preserving clear role boundaries and rigorous safety-document control.","objectives":["Distinguish transferable electrical-safety principles from site-specific rules.","Recognise how UPS, batteries, bypasses and interconnected LV systems affect Safety From The System.","Explain the purpose and lifecycle of safety documentation without inventing client procedures.","Understand the importance of stopping, challenging and escalating when conditions are unclear."],"outcomes":["State what information must be established before accepting that equipment is safe for work.","Explain why normal supply information alone is insufficient.","Describe the conceptual lifecycle of safety documentation.","Identify when a site-specific rule or authorised person must be consulted."],"sections":[["2.1","Transferable Safety Principles","Identify the core discipline that carries from utility/DNO environments into mission-critical systems: defined responsibility, positive identification, isolation, proving, earthing where applicable, control of energy and documented boundaries.","List transferable principles and separate them from company-specific procedure."],["2.2","Roles and Responsibilities","Understand that CP, AP, SAP, AE and other roles carry different authorities and limitations, and that competence includes knowing what cannot be done.","Map role boundaries in a generic organisation."],["2.3","What Can Energise This Equipment?","Adopt the programme’s central behavioural question: do not ask only where the normal supply comes from; determine every credible means by which the equipment can become energised.","Identify normal, alternate and stored-energy sources in a scenario."],["2.4","Isolation Principles","Review isolation conceptually as the deliberate prevention of energy transfer from every relevant source, recognising that exact methods are governed by the applicable Safety Rules.","Evaluate whether a fictional isolation boundary is conceptually complete."],["2.5","Proving Dead and Earthing","Review the purpose of proving dead and earthing within the applicable voltage and rule context, without substituting course content for controlled procedures.","Explain the purpose and limitations of each safeguard."],["2.6","Stored Energy","Consider batteries, capacitive energy, DC systems and other forms of stored energy that may remain after normal AC isolation.","Identify residual-energy questions that must be resolved."],["2.7","Safety Documentation","Understand why safety documents formally communicate boundaries, precautions, responsibilities and conditions for work.","Describe issue, receipt, control and cancellation at principle level."],["2.8","Objections on Safety Grounds","Develop the expectation that uncertainty, conflicting indications or unsafe assumptions are reasons to stop and challenge, not pressures to continue.","Choose an appropriate escalation response in a scenario."],["2.9","Document and Key Control","Understand why lost documents, keys, locks or controlled equipment require formal escalation under the applicable organisational rules.","Explain why informal substitution is unacceptable."],["2.10","Site-Specific Rules Interface","Recognise the boundary between generic training and the organisation’s actual Electrical Safety Rules, Approved Procedures and local instructions.","Identify when the candidate must defer to controlled site documentation."]]},{"id":"m3","num":"03","title":"HV Distribution, Switching, Isolation & Earthing","duration":"6–8 hours structured learning + supervised operational exposure","preamble":"For experienced utility SAPs, this module may contain substantial transferable competence. It establishes the HV baseline while connecting familiar operational discipline to the different topology, commissioning interfaces and resilience requirements found in data centres.","aim":"Confirm and extend HV operational competence within mission-critical distribution systems.","objectives":["Understand generic data-centre HV distribution and transformer feeding arrangements.","Apply disciplined switching-schedule review and operational communication.","Recognise commissioning and resilience implications of HV operations.","Analyse abnormal HV states without providing site-specific switching instructions."],"outcomes":["Explain the purpose and arrangement of generic HV distribution equipment.","Identify the information required before preparing or checking switching.","Describe isolation, proving and earthing principles under controlled rules.","Recognise when HV activity changes downstream resilience."],"sections":[["3.1","HV Distribution Topology","Review typical radial, ring and sectionalised HV arrangements used to feed transformer groups and critical infrastructure.","Trace a generic HV feeder path."],["3.2","HV Switchgear Functions","Understand the operational purpose of breakers, disconnectors, earthing facilities and protection interfaces without assuming identical capability across manufacturers.","Match equipment function to operational purpose."],["3.3","Transformer Feeder Operations","Examine how HV operations interact with transformer availability, LV consequences and alternate downstream supplies.","Identify downstream consequences of transformer feeder unavailability."],["3.4","Switching Philosophy","Use a structured approach to switching: defined objective, known starting state, controlled sequence, verification, communication and restoration planning.","Review a conceptual switching plan for missing information."],["3.5","Switching Schedule Challenge","Develop the habit of independently checking assumptions, equipment identity, sequence logic, interlocks and expected states rather than treating a schedule as automatically correct.","Identify challenge points in a fictional schedule narrative."],["3.6","Isolation and Earthing Interfaces","Review the relationship between HV isolation, proving dead, earthing and downstream LV/transformer conditions.","Explain why both sides of a transformer matter."],["3.7","Protection and Trip Awareness","Understand how protection operation changes the electrical state and what information must be obtained before restoration decisions.","Interpret a conceptual trip event."],["3.8","Commissioning Interfaces","Recognise that newly energised or partially commissioned systems may not have the same configuration or operational maturity as completed plant.","List information required before treating a commissioning system as normal."],["3.9","Loss of Redundancy","Understand that an HV outage may leave downstream load supplied but with reduced resilience, changing the operational risk picture.","Assess a degraded-resilience condition."],["3.10","HV Integration Review","Consolidate HV architecture, operational control, communication and downstream consequences in an integrated scenario.","Complete the conceptual review."]]},{"id":"m4","num":"04","title":"LV Distribution & Multiple-Infeed Philosophy","duration":"8–10 hours structured learning + extensive practical exposure","preamble":"Complex LV distribution is often the largest conversion gap for experienced HV SAPs entering hyperscale data centres. This module treats LV as an operational system in its own right rather than as a simple downstream consequence of the transformer.","aim":"Develop confident analysis of multi-source LV architecture, interconnection and alternative energisation risk.","objectives":["Understand LV switchboard, bus section and coupler arrangements.","Identify multiple infeeds and backfeed possibilities.","Analyse upstream and downstream dependencies before isolation.","Recognise control and auxiliary supplies that can affect equipment state."],"outcomes":["Trace all credible sources to a selected LV section.","Explain how bus couplers and alternate feeds alter isolation requirements.","Recognise backfeed risk from interconnected systems.","State what must be confirmed before declaring an LV system safe for work."],"sections":[["4.1","LV Main Distribution","Build a clear mental model of transformer-fed LV boards, outgoing feeders and principal distribution.","Trace one LV source from transformer to downstream board."],["4.2","Bus Sections","Understand how sectionalised boards create operational flexibility and complexity.","Explain the consequence of section status."],["4.3","Bus Couplers","Examine how couplers can join previously separate supplies and therefore alter possible energisation paths.","Analyse open and closed coupler states."],["4.4","Multiple Infeeds","Identify systems with more than one credible source and avoid assuming the labelled 'normal' source is the only energisation path.","List all possible infeeds in a generic arrangement."],["4.5","Backfeed","Understand how connected downstream equipment, bypasses, alternate feeders or temporary arrangements can create an unexpected feed direction.","Identify potential backfeed mechanisms conceptually."],["4.6","A/B Distribution","Understand diverse power paths and why an activity on one side may still affect the resilience or operating state of the other.","Assess an A-side outage with B-side support."],["4.7","Control and Auxiliary Supplies","Recognise that control power, space heaters, chargers and auxiliary circuits may remain energised independently of the main power circuit.","Identify auxiliary-energy questions."],["4.8","LV Isolation Philosophy","Use source identification, boundary definition and system-state verification to reason about LV isolation under the governing Safety Rules.","Evaluate a conceptual isolation boundary."],["4.9","Temporary and Commissioning States","Understand that temporary links, test supplies and partially commissioned equipment can invalidate assumptions based on final design drawings.","Identify what must be verified physically/documentally."],["4.10","Integrated LV Scenario","Analyse a fictional multi-infeed board and explain remaining energy paths, resilience consequences and missing information.","Complete the integrated LV analysis."]]},{"id":"m5","num":"05","title":"UPS, Batteries & Bypass Arrangements","duration":"10–14 hours structured learning + practical observation","preamble":"UPS systems are central to mission-critical power resilience and a frequent source of misunderstanding for personnel whose previous experience is dominated by conventional AC distribution. The module focuses on understanding energy paths, operating states and the distinction between normal supply and every source capable of sustaining or re-energising the output.","aim":"Develop a robust conceptual and operational understanding of UPS systems, battery energy, bypass arrangements and associated isolation implications.","objectives":["Understand the major functional blocks of a double-conversion UPS.","Trace energy through rectifier, DC link, battery, inverter and bypass paths.","Distinguish static bypass from maintenance bypass.","Analyse normal, degraded and maintenance operating states."],"outcomes":["Explain UPS energy flow in normal and battery operation.","Identify sources that may energise the UPS input, DC system or output.","Explain the operational purpose of static and maintenance bypass.","Recognise when a displayed operating state is insufficient to establish safe conditions."],"sections":[["5.1","UPS Purpose and Architecture","Understand why UPS systems maintain continuity and power quality for critical loads and how the major functional blocks relate.","Label a generic UPS block diagram."],["5.2","Rectifier","Understand the rectifier’s role in converting AC input to DC and supporting the DC link/battery system.","Trace the rectifier energy path."],["5.3","DC Link","Understand the DC link as an internal energy path and why DC conditions remain relevant even when an AC input changes state.","Identify DC-side questions during isolation planning."],["5.4","Battery Systems","Understand batteries as an independent stored-energy source capable of sustaining the DC link and inverter.","Explain why opening an AC source does not eliminate battery energy."],["5.5","Inverter","Understand conversion from DC to controlled AC output and the inverter’s role in normal online operation.","Trace normal inverter-fed output."],["5.6","Static Bypass","Understand the purpose of the static bypass path and how it can provide an alternative AC route to the load under defined conditions.","Compare inverter and static-bypass energy paths."],["5.7","Maintenance Bypass","Understand the separate purpose of a maintenance bypass arrangement and why its state materially affects the safe isolation picture.","Identify how maintenance bypass changes source analysis."],["5.8","Normal Operating State","Build a baseline model of normal double-conversion operation before considering abnormal states.","Describe source-to-load flow in normal operation."],["5.9","Battery Operation","Analyse loss of normal AC input while the battery and inverter sustain the load.","Describe the changed energy source."],["5.10","Bypass Operation","Analyse conditions where the load is supplied through bypass rather than the inverter.","Identify which path is now carrying load."],["5.11","Stored Energy","Consider battery energy and other stored-energy elements that remain present after switching actions.","List stored-energy hazards requiring controlled management."],["5.12","Alternative Energy Paths","Apply the central question 'what can energise this equipment?' to input, bypass, battery and output interfaces.","Identify all credible energy paths in a generic state."],["5.13","Isolation Considerations","Develop a conceptual isolation analysis without substituting for site rules or approved procedures.","State the information required before any isolation decision."],["5.14","Failure Modes","Understand at principle level how rectifier, inverter, battery or bypass conditions can change the operating state.","Match a failure to likely system-state change."],["5.15","Operational Consequences","Relate UPS configuration to downstream continuity, redundancy and risk.","Assess the consequence of losing one UPS path."],["5.16","Restoration Considerations","Understand why restoration requires confirmation of the intended configuration, available sources and downstream state.","Create a conceptual restoration checklist."],["5.17","Integrated UPS Scenario","Analyse a fictional UPS with multiple available paths and state whether sufficient information exists to proceed with a proposed maintenance activity.","Identify remaining sources and unanswered questions."]]},{"id":"m6","num":"06","title":"ATS / STS & Automatic Transfer Systems","duration":"6–8 hours structured learning + practical observation","preamble":"Automatic and static transfer systems can change the source feeding a load without the same human intervention expected on conventional networks. Competence therefore requires understanding not only the normal source, but transfer logic, alternate sources and the conditions that cause source changes.","aim":"Develop the ability to analyse transfer-system architecture, source availability and operational consequences.","objectives":["Understand the purpose of ATS and STS arrangements.","Identify normal and alternate sources.","Recognise automatic transfer as a potential change in energisation path.","Understand control, interlocking and failure implications."],"outcomes":["Explain the difference between automatic and static transfer at principle level.","Identify both available sources to a transfer system.","Recognise when automatic logic could alter the assumed state.","Assess operational consequences of transfer failure or inhibited transfer."],"sections":[["6.1","Transfer-System Purpose","Understand why critical loads require automatic access to alternate sources.","Describe the resilience objective."],["6.2","Normal and Alternate Sources","Identify both source paths before analysing logic or isolation.","Trace two-source supply."],["6.3","ATS Principles","Understand automatic transfer at conceptual level, including source sensing and commanded changeover.","Explain what triggers a transfer in principle."],["6.4","STS Principles","Understand high-speed static transfer between compatible sources at principle level.","Compare ATS and STS purposes."],["6.5","Control Supplies","Recognise that control power availability can determine whether the transfer system operates as expected.","Identify control-power dependencies."],["6.6","Interlocking","Understand the role of mechanical/electrical/logical interlocks in preventing prohibited source combinations.","Explain why interlock status matters."],["6.7","Isolation Implications","Recognise that both normal and alternate sources must be considered when establishing a safe boundary.","Analyse a two-source isolation concept."],["6.8","Abnormal Transfer States","Consider failed transfer, unavailable source, inhibited automatic mode and unexpected switch position.","Choose appropriate stop/check/escalate responses."],["6.9","Operational Consequences","Relate transfer-system state to downstream availability and resilience.","Assess a degraded-source scenario."],["6.10","Integrated Transfer Scenario","Analyse a fictional transfer arrangement and identify all information needed before work proceeds.","Complete the source-state analysis."]]},{"id":"m7","num":"07","title":"Critical Mechanical Electrical Supplies","duration":"5–7 hours structured learning + site-system familiarisation","preamble":"The SAP does not need to become a mechanical engineer, but must understand the electrical consequence of supplying, isolating or restoring critical mechanical systems. In data centres, electrical availability and thermal resilience are tightly coupled.","aim":"Develop sufficient understanding of critical mechanical electrical dependencies to make safe and operationally informed electrical decisions.","objectives":["Recognise the major categories of electrically supplied critical mechanical plant.","Understand redundancy and dependency at an operational level.","Assess the consequence of removing electrical supply from mechanical systems.","Coordinate electrical restoration with system-operational needs."],"outcomes":["Identify critical mechanical loads and their electrical sources.","Explain why loss of a mechanical supply can become a data-hall risk.","Recognise dependency on control and auxiliary systems.","Include mechanical consequences in outage and restoration planning."],"sections":[["7.1","Why Mechanical Dependencies Matter","Understand the relationship between electrical continuity and cooling/environmental control.","Describe the electrical-to-thermal dependency."],["7.2","Cooling Systems","Identify broad categories of cooling plant and why source resilience matters.","Map a generic cooling electrical supply."],["7.3","AHUs and Air Movement","Understand AHUs/fans as critical electrically supplied assets in some architectures.","Identify supply and control dependencies."],["7.4","Pumps","Recognise duty/standby pump arrangements and the implications of electrical isolation.","Assess redundancy before an outage."],["7.5","Controls and Auxiliaries","Identify BMS/control power, actuators and auxiliary circuits that may have separate supplies.","List auxiliary dependencies."],["7.6","Redundancy","Understand N, N+1 and similar concepts only to the extent needed to assess electrical operational consequence.","Evaluate loss of one element."],["7.7","Isolation Consequences","Determine which operational stakeholders must understand the impact of electrical isolation on critical mechanical plant.","Create an impact statement."],["7.8","Restoration Dependencies","Understand that restoration sequence may need coordination with controls, valves, pumps or wider system conditions.","Identify coordination requirements."],["7.9","Integrated Mechanical Dependency Scenario","Analyse an electrical outage affecting part of a fictional cooling system.","State the operational consequences and required coordination."]]},{"id":"m8","num":"08","title":"Commissioning, Load Banks & Integrated Systems Testing","duration":"8–10 hours structured learning + commissioning exposure","preamble":"Commissioning creates temporary states that may be deliberately different from the final operational design. The SAP must understand where temporary supplies, test equipment, load banks and staged energisation alter the normal system model.","aim":"Develop safe operational understanding of commissioning configurations, load-bank testing and integrated systems testing interfaces.","objectives":["Understand progressive energisation and commissioning lifecycle.","Recognise temporary and test configurations.","Understand load-bank purpose and electrical interfaces.","Maintain configuration awareness during integrated testing."],"outcomes":["Explain why commissioning state must be verified rather than assumed from final design.","Identify temporary sources or connections that may affect isolation.","Describe staged load-bank testing at principle level.","Recognise the operational-control interfaces during integrated systems testing."],"sections":[["8.1","Commissioning Lifecycle","Understand the transition from installation through energisation, functional testing and integrated operation.","Place an activity within a generic commissioning lifecycle."],["8.2","Progressive Energisation","Understand controlled introduction of energy as systems are completed and verified.","Identify information required before energisation."],["8.3","Temporary Configurations","Recognise that temporary links, feeds or test arrangements can exist outside the final-state model.","List temporary-state verification questions."],["8.4","Load Banks","Understand load banks as controlled test loads used to prove system performance.","Explain purpose without producing connection instructions."],["8.5","Incremental Loading","Understand staged loading and why system performance is observed progressively.","Describe what is being proven conceptually."],["8.6","Sustained Load Proving","Understand why sustained operation at representative load can reveal thermal or performance issues.","Identify monitored outcomes conceptually."],["8.7","Transfer Testing","Understand tests intended to demonstrate continuity and transfer between power paths.","Identify possible changes in source state."],["8.8","Integrated Systems Testing","Understand how electrical, controls and mechanical systems are tested together under representative scenarios.","Describe why cross-system coordination matters."],["8.9","Temporary Connections","Recognise temporary cables and connections as controlled configuration changes requiring clear ownership and documentation.","Identify configuration-control requirements."],["8.10","Controlled Re-energisation","Understand restoration to intended operational state after test conditions are removed.","Create a conceptual state-verification checklist."],["8.11","Configuration Control","Understand why drawings, labels, test status and actual equipment state must remain aligned.","Identify consequences of poor configuration control."],["8.12","Integrated Commissioning Scenario","Analyse a fictional temporary test arrangement and identify what must be verified before operational decisions are made.","Complete the temporary-state analysis."]]},{"id":"m9","num":"09","title":"Abnormal Conditions, Trips & Restoration","duration":"7–9 hours structured learning + scenario practice","preamble":"Authorisation competence is tested most severely when the system is not in its expected state. This module develops disciplined response to trips, conflicting indications, degraded redundancy and unexpected energisation risk.","aim":"Develop safe, structured judgement during abnormal electrical conditions and restoration planning.","objectives":["Recognise when the actual system state differs from expectation.","Prioritise safety, information gathering and escalation over premature restoration.","Analyse loss of redundancy and alternate-source consequences.","Use structured restoration reasoning."],"outcomes":["Respond appropriately to conflicting or incomplete system information.","Identify when further switching should stop pending clarification.","Explain the difference between restoring supply and restoring the intended safe configuration.","Communicate abnormal conditions clearly."],"sections":[["9.1","Abnormal-State Mindset","Treat unexpected conditions as a new system state requiring fresh analysis rather than forcing the system back to an assumed normal.","Apply stop-assess-verify thinking."],["9.2","Unexpected Trips","Understand that a trip is an indication of an event, not merely an inconvenience to be reset.","List information required before restoration consideration."],["9.3","Failed Switching","Recognise equipment that does not achieve the expected state and the need to control the resulting uncertainty.","Choose a safe escalation response."],["9.4","Conflicting Indications","Analyse discrepancies between local indication, remote monitoring and expected position.","Identify which assumptions must be suspended."],["9.5","Unexpected Energisation Risk","Respond to any evidence that an isolated or expected-dead system may be energised.","State the immediate safety principle: stop and re-establish conditions under the applicable rules."],["9.6","Loss of Redundancy","Assess how equipment unavailability changes resilience and acceptable operational risk.","Describe degraded-state consequences."],["9.7","UPS Abnormal Conditions","Apply UPS source analysis to inverter, bypass, battery and unavailable-source states.","Identify remaining energy paths."],["9.8","ATS/STS Abnormal Conditions","Analyse failed, inhibited or unexpected transfer states.","Identify available sources and actual load path."],["9.9","Communication Failure","Recognise that unclear control-room/site communication is itself an operational risk.","Draft a concise abnormal-state briefing."],["9.10","Restoration Planning","Separate urgency to restore service from the disciplined need to understand cause, state, dependencies and intended final configuration.","Build a conceptual restoration decision tree."],["9.11","Integrated Abnormal Scenario","Work through a multi-system degraded state where several assumptions are deliberately challenged.","Document safe decisions and missing information."]]},{"id":"m10","num":"10","title":"Integrated Mock Authorisation Assessment","duration":"Variable; undertaken only after prerequisite competence is demonstrated","preamble":"The final module consolidates architecture, electrical safety, HV, LV, UPS, transfer systems, commissioning and abnormal-state judgement. It is preparation for formal assessment, not a substitute for the organisation’s authorisation process.","aim":"Provide an integrated evidence-based rehearsal of the knowledge, judgement and communication expected before recommendation for formal authorisation assessment.","objectives":["Test integrated system understanding rather than isolated facts.","Assess safety reasoning and ability to identify missing information.","Evaluate operational communication and challenge behaviour.","Identify final competency gaps requiring targeted closure."],"outcomes":["Demonstrate coherent reasoning across multiple systems.","Explain and defend decisions using evidence and applicable principles.","Recognise personal limits and escalate appropriately.","Produce a clear readiness picture by competency domain."],"sections":[["10.1","Assessment Orientation","Understand what the mock assessment is designed to test and what it cannot confer.","Review readiness prerequisites."],["10.2","Architecture Reconstruction","Explain a generic integrated architecture from limited information.","Reconstruct the system."],["10.3","Safety Reasoning","Identify energy sources, boundaries and missing controlled information in an integrated case.","State what must be established before work."],["10.4","HV/LV Interface","Analyse an event crossing transformer and LV operational boundaries.","Explain consequences on both sides."],["10.5","UPS and Alternate Sources","Analyse a mixed UPS/bypass scenario with stored energy.","Identify all credible sources."],["10.6","Transfer Systems","Assess automatic-transfer state and downstream consequences.","Determine actual and potential supply paths."],["10.7","Commissioning State","Analyse a temporary test configuration that differs from final design.","Identify configuration-control risks."],["10.8","Abnormal Condition","Respond to conflicting indications and loss of redundancy.","Document stop/check/escalate decisions."],["10.9","Operational Communication","Give a concise operational briefing of system state, limitations and required next action.","Produce the briefing."],["10.10","Competency Review","Review performance by domain and create targeted development actions for any deficiency.","Complete the development-gap review."]]}],"programObjectives":["Recognise and build on existing transferable AP/SAP competence rather than automatically starting from zero.","Develop a complete mental model of mission-critical electrical architecture before expecting operational decision-making.","Identify every credible source of electrical energy, not merely the normal source.","Integrate structured technical learning with supervised operational exposure and evidence.","Create a transparent competency record that can be reviewed by mentors and Authorising Engineers.","Progress candidates according to demonstrated competence rather than elapsed time."],"learningOutcomes":[["System comprehension","Reconstruct and explain mission-critical electrical power paths, including alternate and resilient configurations."],["Electrical safety","Identify credible energy sources and understand the principles required to establish and maintain safe working conditions."],["Operational judgement","Recognise missing information, challenge unsafe assumptions and make appropriately bounded decisions."],["Practical competence","Build validated evidence through observed, assisted and demonstrated operational activity."],["Abnormal conditions","Reason through trips, failed transfers, unexpected states and degraded resilience."],["Assessment preparation","Demonstrate consolidated competence sufficient to justify consideration for formal authorisation assessment."]],"tnaItems":["HV operational experience","Previous/current authorisations","Voltage-level exposure","Switching","Isolation planning","Proving dead & earthing","Safety-document experience","Protection knowledge","LV operational experience","UPS exposure","Battery systems","ATS / STS","Generators (where applicable)","Commissioning","Temporary supplies","Control systems","Data-centre experience","Mission-critical experience","Formal technical training","Available competency evidence"],"levels":["No experience","Awareness","Working knowledge","Practical experience","Demonstrated competence","Previously authorised / validated"]};
const CURRICULUM_V3={cycles:[["01","Electrical & System Orientation","Electrical principles are established and immediately connected to the data-centre power chain."],["02","Sources & Energy Paths","Normal, alternative and stored-energy paths are traced across interacting systems."],["03","Equipment & Operating States","Equipment function is developed into recognition of actual operating state."],["04","Faults, Protection & Source Behaviour","Fault paths, source characteristics and protective behaviour are connected."],["05","Safety Application","Technical understanding is applied to boundaries, isolation concepts, interlocks and documentation."],["06","Commissioning & Changing Configuration","Temporary and test states are superimposed on the design architecture."],["07","Abnormal Conditions","Trips, failed transfers, degraded redundancy and conflicting information are introduced."],["08","Integrated Competence","The candidate reasons across the complete electrical system without artificial module boundaries."]],assessment:[["Recognition","Identify equipment, symbols and states."],["Explanation","Explain the principle in the candidate's own words."],["Visual reasoning","Label, trace, reconstruct or annotate a diagram."],["Application","Apply knowledge to a changed system state."],["Diagnostic reasoning","Identify inconsistencies, missing information and unsafe assumptions."],["Operational judgement","State what can and cannot be concluded and when escalation is required."],["Practical evidence","Record observed, assisted and demonstrated activity for validation."],["Integration","Reason across several interacting systems."]]};
const V3={
m1:[["1.1","Electrical quantities in data-centre context","Re-establish voltage, current, impedance, active and apparent power, power factor, frequency and energy, then connect each directly to loading, faults, UPS ratings and source compatibility.","Match each quantity to a mission-critical consequence."],["1.2","AC, DC and three-phase behaviour","Build AC/DC, frequency, phase sequence and phase relationship from first principles before applying them to UPS conversion and source transfer.","Mark AC and DC sections on a generic power chain."],["1.3","Conductors and return paths","Develop phase, neutral, protective conductor and combined conductor concepts into normal-current and fault-current path understanding.","Annotate a generic five-conductor feeder and trace return paths."],["1.4","Data-centre power chain","Build utility/HV source, HV distribution, transformer, LV main distribution and critical loads as a coherent engineering system.","Reconstruct the initial power chain without the completed drawing."],["1.5","SLD language and tagging","Learn switching symbols, sources, transformers, protection, measurement, busbars, UPS elements, interlocks, equipment tags and drawing continuations while recognising site-specific conventions.","Decode a fictional SLD legend and identify what requires confirmation."],["1.6","Redundancy and resilience","Introduce N, N+1, duplicated paths and shared redundancy as system concepts and examine the consequence of equipment unavailability.","Compare normal and degraded capacity states."],["1.7","A/B paths and bus coupling","Add second paths, bus sections and couplers so the candidate sees how network state creates additional energisation routes.","Change a coupler state and reassess all credible sources."],["1.8","Architecture reconstruction","Progress from reading to rebuilding a credible generic SLD in layers.","Produce and explain a simplified architecture overlay."],["1.9","Known, inferred and unknown","Separate what a drawing proves from what requires controlled drawings, settings, OEM information or operational confirmation.","Mark knowns and unknowns on a fictional SLD."],["1.10","Orientation development check","Test fundamentals, symbols, tracing and architecture before complexity increases.","Complete mixed recognition, tracing and explanation tasks."]],
m2:[["2.1","Hazards and electrical condition","Connect shock, arc, fault and stored-energy hazards to actual equipment condition.","Classify hazards in a fictional state."],["2.2","Roles, authority and limits","Distinguish competence, appointment and organisational authority.","Resolve a role-boundary scenario."],["2.3","All credible energy sources","Develop the recurring question of every normal, alternate, stored, control and temporary source capable of energising equipment.","Identify source categories on a layered SLD."],["2.4","Isolation as a system condition","Understand isolation conceptually as control of all relevant energy paths, governed in practice by applicable Safety Rules.","Judge whether a fictional boundary is complete."],["2.5","Verification and residual energy","Understand why expected state, indication and elapsed time do not replace approved verification and OEM requirements.","Identify what remains to be established in a de-energisation scenario."],["2.6","Interlock philosophy","Learn mechanical, electrical and trapped-key interlocks as safeguards defining permitted relationships; unexpected refusal is information to investigate.","Interpret a fictional interlock dependency."],["2.7","Safety documents and communication","Understand controlled communication of plant identity, boundaries, precautions and responsibilities.","Review a fictional document for omissions."],["2.8","PPE and instruments","Recognise that selection depends on task, voltage, prospective energy and controlled rules rather than generic course prescription.","Identify information needed before selection."],["2.9","Stop, challenge and escalate","Treat conflicting indications and missing information as unresolved conditions.","Respond to an expected-versus-observed discrepancy."],["2.10","Safety application gate","Combine sources, boundaries, interlocks and incomplete information.","State knowns, unknowns and required escalation."]],
m3:[["3.1","HV role in the power chain","Place HV distribution within complete data-centre architecture.","Trace fictional HV feeders to LV consequences."],["3.2","Switching devices and capability","Differentiate breaker, switch, disconnector, earthing and fused functions by capability.","Match symbols to functional descriptions."],["3.3","Ratings and fault duty","Introduce rated current, breaking capacity and short-time withstand as constraints linked to prospective fault conditions.","Interpret a fictional equipment rating."],["3.4","Draw-out equipment states","Understand connected, test/disconnected and withdrawn concepts where applicable and the limits of position indication.","Determine what a generic position does and does not establish."],["3.5","HV cubicles and switchboard functions","Recognise incomer, feeder, transformer protection, metering and bus-section functions.","Label a fictional HV lineup."],["3.6","Transformer interface","Connect HV feeder state with transformer and LV consequences including downstream energisation possibilities.","Explain why HV isolation alone may not answer every safety question."],["3.7","Protection and metering","Understand CT/VT and protection/measurement interfaces conceptually.","Identify information provided and limitations."],["3.8","Switching-plan discipline","Analyse objective, starting state, expected result, verification, communication and back-out without site-specific switching instructions.","Critique a fictional plan extract."],["3.9","Earthing and boundaries","Connect proving and earthing concepts to applicable rules and equipment design.","Explain the purpose of a fictional safety boundary."],["3.10","HV development check","Assess recognition, architecture, state and HV/LV interaction.","Complete an integrated HV check."]],
m4:[["4.1","LV distribution from first principles","Build transformer secondary, main boards, downstream distribution and loads using credible busbar and breaker arrangements.","Trace an LV path end to end."],["4.2","Fault types and paths","Distinguish overload, short circuit and insulation/earth fault and connect each to current path.","Trace generic fault paths."],["4.3","Protection fundamentals","Develop fuse, breaker, residual protection and insulation monitoring before electronic trip functions.","Match protection to the condition it detects."],["4.4","Earthing-system concepts","Teach TT, TN-S, TN-C and IT through neutral, exposed-conductive-part and fault-path relationships, with design-specific caveats.","Compare first-fault behaviour on generic diagrams."],["4.5","Neutral and source boundaries","Explore neutral-earth relationships and why source transfer or transformer boundaries change the questions an operator must ask.","Identify neutral information required before analysing source change."],["4.6","LV breakers and trip functions","Introduce ACB/MCCB ratings and long, short, instantaneous and earth-protection concepts.","Read a fictional trip-unit display conceptually."],["4.7","Multiple incomers and couplers","Add second incomers, sections and couplers to show changing energisation routes and fault contribution.","Compare coupled and uncoupled states."],["4.8","Selectivity concepts","Explain coordinated protection and why actual conclusions depend on the approved study and current configuration.","Interpret a conceptual time-current relationship."],["4.9","Alternative feeds and backfeed awareness","Integrate UPS, transfer and interconnection paths into LV source identification.","Find a concealed alternative path on a generic SLD."],["4.10","LV integrated check","Combine conductors, faults, earthing, protection and multiple-source architecture.","Complete a diagram-based challenge."]],
m5:[["5.1","UPS purpose","Introduce continuity, conditioning and stored energy within the critical power chain.","Place the UPS in a generic architecture."],["5.2","Double-conversion path","Build rectifier, DC link and inverter progressively so AC/DC/AC conversion is understood.","Trace the normal conversion path."],["5.3","Capacitors and residual energy","Explain stored energy and discharge conceptually; actual safe times and verification come from approved OEM/site information.","Explain why removal of AC does not prove absence of internal energy."],["5.4","Battery as a source","Treat battery systems as independent DC energy sources with their own state and hazards.","Trace battery-to-load flow after normal input loss."],["5.5","Static bypass","Introduce bypass source relationship and operating state without universalising vendor behaviour.","Compare conversion and bypass-fed paths."],["5.6","Maintenance bypass","Explain purpose and topology as design-specific.","Identify which fictional parts remain energised in bypass."],["5.7","Synchronisation relationship","Connect voltage, frequency, phase sequence and phase relationship to source compatibility.","Identify information needed before compatibility can be judged."],["5.8","Parallel UPS and load sharing","Introduce modular systems, redundancy and load sharing without assuming universal control logic.","Assess a fictional N+1 state."],["5.9","Capacity and residual margin","Use kW, kVA, power factor and unit availability to reason about remaining capacity.","Complete a fictional capacity calculation."],["5.10","UPS energy-source gate","Combine normal input, bypass, battery, DC link and downstream paths.","Identify all credible sources and unknowns."]],
m6:[["6.1","Transfer-system purpose","Relate continuity to preferred and alternate sources.","Identify ATS and STS functions."],["6.2","Source compatibility","Revisit voltage, frequency, phase sequence and phase relationship.","Judge whether enough information exists to compare sources."],["6.3","Open transition","Explain break-before-make conceptually and its load consequence.","Order conceptual transfer states."],["6.4","Controlled overlap","Explain closed-transition concepts as design-specific and dependent on approved synchronising/protection conditions.","Identify additional questions raised by source overlap."],["6.5","ATS states","Recognise preferred, alternate, automatic, inhibited and incomplete states.","Determine source from a fictional state diagram."],["6.6","STS states","Introduce static transfer for compatible sources and selected critical loads.","Compare ATS and STS functions."],["6.7","Coupling and paralleling","Explain how source coupling changes fault contribution, neutral relationships and protection assumptions.","Identify engineering information needed before a conclusion."],["6.8","Interlocks and refusal","Treat refused operation as information, not an obstacle to defeat.","Identify categories to investigate."],["6.9","Failed transfer","Develop judgement when source availability, indications and load state disagree.","State knowns, unknowns and escalation."],["6.10","Transfer gate","Combine UPS bypass, transfer and LV source paths.","Trace actual and potential sources."]],
m7:[["7.1","Mechanical electrical dependencies","Connect cooling/environmental systems to electrical continuity.","Map a mechanical load to its source."],["7.2","Motors, drives and control power","Introduce motors, VFDs and separate control supplies at AP/SAP-relevant depth.","Identify main and control paths."],["7.3","AHU and cooling systems","Understand electrical dependencies without attempting mechanical qualification.","Trace a fictional AHU supply."],["7.4","Pumps and redundant trains","Relate redundant mechanical trains to A/B electrical architecture.","Identify consequence of losing one train."],["7.5","Automatic transfer","Integrate ATS-backed mechanical loads with source availability.","Determine the supplying source."],["7.6","Loss of redundancy","Distinguish continued operation from normal resilience.","Explain why running does not mean fully resilient."],["7.7","Power-quality interaction","Connect motors/VFDs to harmonics and protection conceptually.","Identify approved information required for real conclusions."],["7.8","Operational coordination","Develop cross-discipline communication before changing critical supplies.","Draft a fictional impact briefing."],["7.9","Restoration consequences","Consider verification when returning mechanical supplies to intended state.","Identify configuration checks."],["7.10","Mechanical-interface check","Assess source, transfer, control and redundancy understanding.","Complete an integrated scenario."]],
m8:[["8.1","Commissioning changes state","Establish that design, construction, test and operational states may differ.","Compare design and current test configurations."],["8.2","Progressive energisation","Explain staged energisation conceptually under approved procedures and authorised control.","Identify prerequisite evidence categories."],["8.3","Temporary supplies and connections","Recognise temporary cables, supplies and links as credible energy paths.","Add a temporary path and reassess sources."],["8.4","Load-bank purpose","Explain load banks as controlled test loads used to prove performance.","Identify the intended test outcome."],["8.5","Staged and sustained loading","Connect loading with thermal response, voltage stability and protection observation without prescribing site percentages or durations.","Interpret fictional test results."],["8.6","Transfer testing","Integrate UPS/ATS/STS source changes into commissioning awareness.","Predict systems requiring observation."],["8.7","Integrated Systems Testing","Explain whole-system interaction testing.","Map a fictional IST event across modules."],["8.8","Inhibited automation and unavailable plant","Recognise how temporary overrides and unavailable equipment change assumptions.","Identify changed conditions on a test-state diagram."],["8.9","Return to intended configuration","Require positive verification after testing rather than assuming normality.","Compare before, test and after states."],["8.10","Configuration-control gate","Assess temporary paths, test states and restoration awareness.","Reconstruct the system as it actually exists."]],
m9:[["9.1","Source impedance and fault current","Connect source/network impedance to prospective fault current.","Compare two fictional source conditions qualitatively."],["9.2","Breaking and withstand capability","Relate prospective fault conditions to breaker and switchboard capability concepts.","Interpret fictional Icu/Ics/Icw information."],["9.3","Protection selectivity","Develop the purpose of coordinated protection and configuration dependence.","Identify the approved study required for a real conclusion."],["9.4","Zone-selective interlocking","Explain communication-assisted selectivity conceptually and retain manufacturer-specific caveats.","Describe the intended protection objective."],["9.5","UPS-fed fault behaviour","Teach that inverter fault capability is equipment- and state-specific and may differ from transformer supply.","Reject a definitive answer where OEM/study data is absent."],["9.6","Harmonics and non-linear loads","Introduce harmonic current, THD and effects on neutrals, transformers and voltage waveform.","Identify common non-linear load categories."],["9.7","Other power-quality conditions","Cover dips, interruptions, transients and phase imbalance as conditions to recognise and escalate.","Match symptoms to categories."],["9.8","Unexpected trips and indications","Develop structured response when reality contradicts expected state.","Separate observation, inference and required confirmation."],["9.9","Controlled restoration","Treat restoration as re-establishing actual configuration and boundaries, not blindly reversing actions.","Review a fictional restoration state."],["9.10","Abnormal-condition gate","Combine protection, power quality, transfer and configuration discrepancies.","Complete a stop/challenge/escalate scenario."]],
m10:[["10.1","Integrated reconstruction","Rebuild a multi-source fictional SLD from controlled information.","Create the current-state architecture."],["10.2","Whole-system source assessment","Identify normal, alternate, stored, control and temporary energy sources.","Mark every credible source category."],["10.3","Operational boundaries","Define conceptual boundaries while identifying what only site rules can resolve.","Produce a boundary statement."],["10.4","HV/LV/UPS interaction","Analyse an event crossing transformer, LV and UPS states.","Explain system consequences."],["10.5","Transfer and redundancy judgement","Determine actual source, alternate paths and degraded resilience.","State what remains and what has been lost."],["10.6","Commissioning challenge","Introduce temporary configuration and inhibited automation.","Update the current-state SLD."],["10.7","Protection and abnormal indications","Add a protection event or conflicting indication.","Identify knowns, unknowns and evidence required."],["10.8","Operational communication","Require concise communication of state, limitations and escalation.","Deliver a written briefing."],["10.9","Practical evidence consolidation","Review O/A/D evidence and identify gaps knowledge testing cannot close.","Produce targeted development actions."],["10.10","Mock authorisation assessment","Assess integrated knowledge, application and judgement; passing supports readiness review only.","Complete mock and deficiency review."]]
};for(const m of DATA.modules){if(V3[m.id])m.sections=V3[m.id]}

const app=document.getElementById('app'),nav=document.getElementById('nav');
document.getElementById('menuToggle').onclick=()=>nav.classList.toggle('open');
nav.addEventListener('click',()=>nav.classList.remove('open'));
const state=JSON.parse(localStorage.getItem('powertecTrainingV1')||'{"completedLessons":[],"tna":{}}');
function save(){localStorage.setItem('powertecTrainingV1',JSON.stringify(state))}
function esc(s){return String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function goto(h){location.hash=h;window.scrollTo(0,0)}
function pageHero(k,t,c){return `<section class="page-hero"><div class="container"><div class="eyebrow">${k}</div><h1>${t}</h1><p class="lead">${c}</p></div></section>`}
function home(){
return `<section class="front-page">
  <div class="front-bg front-bg-1"></div>
  <div class="front-bg front-bg-2"></div>
  <div class="front-bg front-bg-3"></div>
  <div class="front-overlay"></div>
  <div class="front-content">
    <div class="front-kicker">DATA CENTRE AP/SAP DEVELOPMENT PROGRAMME</div>
    <h1>Structured development for mission-critical electrical operations.</h1>
    <p class="front-synopsis-main">A progressive, integrated competency pathway for experienced electrical operational personnel transitioning into complex data-centre environments.</p>
    <p class="front-synopsis-sub">Build whole-system understanding across HV, LV, UPS, transfer systems, protection, critical mechanical supplies and commissioning — with knowledge, judgement and practical evidence developed together.</p>
    <button class="front-enter" onclick="goto('#/programme')">Explore programme <span>→</span></button>
  </div>
</section>`;
}
function programme(){const process=["Programme Orientation","Candidate Profile","Baseline Assessment","Training Needs Analysis","Development Pathway","Architecture Development","Technical Learning","Guided Site Exposure","Practical Evidence","Knowledge Assessment","Scenario Assessment","Competency Gates","Gap Closure","Mock Assessment","AE Desktop Review","Formal Assessment Recommendation"];return pageHero("PROGRAMME OVERVIEW","A defined route from experience to demonstrable competence.","A structured conversion and development pathway. It does not replace company Safety Rules, site procedures or formal authorisation.")+`<div class="container content-grid"><aside class="toc"><a href="#purpose">Purpose</a><a href="#aim">Aim & objectives</a><a href="#outcomes">Outcomes</a><a href="#entry">Entry</a><a href="#duration">Duration</a><a href="#model">65/35 model</a><a href="#process">Process</a><a href="#assessment">Assessment</a><a href="#roles">Roles</a></aside><article class="prose">
<section id="purpose"><div class="kicker">Purpose</div><h2>Why the programme exists</h2><p>Powertec Training provides a structured pathway for electrical operational personnel who need to translate existing competence into the architecture, risk profile and operational demands of mission-critical data centres.</p><div class="callout"><strong>Course completion does not confer authorisation.</strong><p>The strongest platform outcome is a recommendation that a candidate appears ready for formal authorisation assessment.</p></div></section>
<section id="aim"><div class="kicker">Aim</div><h2>Programme aim</h2><p>To provide a structured, evidence-based development pathway enabling electrical operational personnel to develop, demonstrate and document the knowledge, system understanding, judgement and practical competence required to progress toward AP/SAP authorisation within mission-critical data-centre environments.</p><h3>Objectives</h3><ul>${DATA.programObjectives.map(x=>`<li>${x}</li>`).join('')}</ul></section>
<section id="outcomes"><div class="kicker">Outcomes</div><h2>Desired learning outcomes</h2><div class="outcome-grid">${DATA.learningOutcomes.map(x=>`<div class="outcome"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></section>
<section id="entry"><div class="kicker">Entry</div><h2>Entry requirements are evidence-led, not assumed.</h2><p>Existing competence is captured through the Entry TNA rather than inferred from job title alone.</p><button class="btn primary" onclick="goto('#/tna')">Open Entry TNA</button></section>
<section id="duration"><div class="kicker">Duration</div><h2>Indicative 8–12 weeks for experienced SAP conversion.</h2><p>Duration is indicative only. Progression is competency-based rather than calendar-based.</p><div class="feature-list">${[["Week 1","Baseline, TNA and architecture."],["Week 2","LV and critical-power architecture."],["Week 3","UPS, bypass, transfer systems and alternate sources."],["Week 4","Safety Rules and documentation application."],["Weeks 5–6","Structured operational exposure."],["Weeks 7–8","Planning, supervised activity and scenarios."],["Week 9","Targeted gap closure."],["Week 10+","Mock assessment and readiness review."]].map((x,i)=>`<div class="feature"><div class="n">${String(i+1).padStart(2,'0')}</div><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div></section>
<section><div class="kicker">Educational method</div><h2>Start with first principles. Build the complete system progressively.</h2><p>Electrical fundamentals remain core teaching for every candidate. Prior AP/SAP experience affects pace and depth, not whether the foundation is covered. Concepts return repeatedly at increasing complexity: principle, equipment, architecture, interaction, operational application and integrated judgement.</p><div class="principle">Technical subjects are separated for teaching clarity; competence is developed and assessed through their interaction as one electrical system.</div><div class="cycle-grid">${CURRICULUM_V3.cycles.map(c=>`<div class="cycle-card"><b>CYCLE ${c[0]}</b><h3>${c[1]}</h3><p>${c[2]}</p></div>`).join("")}</div></section><section id="model"><div class="kicker">Development model</div><h2>65% operational / 35% structured.</h2><div class="model"><div class="operational"><h3>65% Operational Development</h3><p>Site exposure, shadowing, SLD tracing, plant familiarisation, switching, isolation, earthing, safety-document processes, commissioning interfaces, supervised activities and restoration.</p></div><div class="structured"><h3>35% Structured Development</h3><p>Technical modules, diagrams, architecture exercises, scenarios, knowledge checks, reflection, evidence collation and assessment preparation.</p></div></div></section>
<section id="process"><div class="kicker">Process</div><h2>Complete development pathway</h2><div class="process">${process.map((x,i)=>`<div class="step"><b>${String(i+1).padStart(2,'0')}</b><strong>${x}</strong></div>`).join('')}</div></section>
<section id="assessment"><div class="kicker">Assessment philosophy</div><h2>Educate, check understanding, then increase complexity.</h2><p>Assessment starts with recognition and explanation, then develops through diagrams, tracing, state analysis, calculations where appropriate, diagnostic reasoning, operational judgement and supervised practical evidence.</p><div class="assessment-grid">${CURRICULUM_V3.assessment.map((a,i)=>`<div class="assess-card"><b>${String(i+1).padStart(2,"0")}</b><h3>${a[0]}</h3><p>${a[1]}</p></div>`).join("")}</div></section>
<section id="roles"><div class="kicker">Roles</div><h2>Clear responsibilities</h2><div class="pathway-grid"><div class="pathway"><span class="tag">CANDIDATE</span><h3>Candidate</h3><p>Owns learning, evidence, reflection and demonstration of competence.</p></div><div class="pathway"><span class="tag">MENTOR</span><h3>Mentor AP/SAP</h3><p>Provides targeted operational coaching and validates practical evidence.</p></div><div class="pathway"><span class="tag">AE</span><h3>Authorising Engineer</h3><p>Reviews competency evidence, identifies deficiencies and governs formal assessment.</p></div><div class="pathway"><span class="tag">ADMIN</span><h3>Training Administrator</h3><p>Maintains programme content and controlled training administration.</p></div></div></section></article></div>`}
function pathways(){return pageHero("DEVELOPMENT PATHWAYS","Different starting points. One competency framework.","The programme recognises that an experienced SAP conversion route differs from a CP/AP development route.")+`<section class="section"><div class="container pathway-grid"><div class="pathway"><span class="tag">PATHWAY 01</span><h2>Experienced SAP → Data Centre SAP Conversion</h2><p>For established SAPs from DNO, utility, industrial, infrastructure, renewables or comparable operational environments.</p><h3>Likely development emphasis</h3><p>Complex LV distribution, A/B paths, UPS, battery energy, bypass, ATS/STS, commissioning states, critical mechanical dependencies and data-centre operating philosophy.</p><button class="btn primary" onclick="goto('#/tna')">Complete conversion TNA</button></div><div class="pathway"><span class="tag">PATHWAY 02</span><h2>CP/AP → Data Centre SAP Development</h2><p>For personnel progressing toward greater operational responsibility and requiring broader development across technical, procedural and judgement competencies.</p><h3>Progression principle</h3><p>Competency gates determine progression. Time served alone cannot release the candidate to formal assessment.</p><button class="btn primary" onclick="goto('#/tna')">Complete development TNA</button></div></div></section>`}
function modulesPage(){return pageHero("COURSE STRUCTURE","Ten integrated technical modules.","Each module has its own preamble, aim, objectives, learning outcomes, duration and structured sections. New users begin at 0%.")+`<section class="section"><div class="container"><div class="course-grid">${DATA.modules.map(m=>{const done=m.sections.filter(s=>state.completedLessons.includes(m.id+':'+s[0])).length;return `<article class="module-card" onclick="goto('#/module/${m.id}')"><div class="num">MODULE ${m.num}</div><h3>${m.title}</h3><p>${m.preamble}</p><div class="meta">${m.duration}</div><div class="progressbar"><i style="width:${Math.round(done/m.sections.length*100)}%"></i></div><div class="meta" style="margin-top:8px">${done} / ${m.sections.length} sections completed</div></article>`}).join('')}</div></div></section>`}
function modulePage(id){const m=DATA.modules.find(x=>x.id===id);if(!m)return modulesPage();const done=m.sections.filter(s=>state.completedLessons.includes(m.id+':'+s[0])).length,pct=Math.round(done/m.sections.length*100);return pageHero(`MODULE ${m.num}`,m.title,m.preamble)+`<div class="container module-layout"><aside class="module-side"><div class="status"><div class="kicker">Your progress</div><strong style="font-size:30px">${pct}%</strong><div class="progressbar"><i style="width:${pct}%"></i></div><p>${done} of ${m.sections.length} sections completed.</p></div><div class="status"><div class="kicker">Expected duration</div><p>${m.duration}</p></div><button class="btn" style="width:100%" onclick="goto('#/modules')">← All modules</button></aside><article><section class="prose" style="margin-bottom:40px"><div class="kicker">Module aim</div><h2 style="font-size:34px">${m.aim}</h2><h3>Objectives</h3><ul>${m.objectives.map(x=>`<li>${x}</li>`).join('')}</ul><h3>Learning outcomes</h3><ul>${m.outcomes.map(x=>`<li>${x}</li>`).join('')}</ul></section><div class="lesson-list">${m.sections.map(s=>{const key=m.id+':'+s[0],isDone=state.completedLessons.includes(key);return `<section class="lesson"><button class="lesson-head" onclick="this.parentElement.classList.toggle('open')"><span class="code">${s[0]}</span><strong>${s[1]}</strong><span class="${isDone?'done':'badge'}">${isDone?'COMPLETED':'OPEN'}</span></button><div class="lesson-body"><div class="teach"><h4>Teaching focus</h4><p>${s[2]}</p></div><div class="activity"><div class="kicker">Applied learning activity</div><strong>${s[3]}</strong></div><div class="check"><strong>Incremental assessment</strong><p>This principle returns later in diagram, state-analysis and integrated scenario assessments.</p></div><p><strong>Completion rule:</strong> learning completion is separate from knowledge performance, integrated competence and practical validation.</p>${isDone?`<span class="done">✓ Section completed</span> <button class="btn" onclick="toggleLesson('${key}')">Undo completion</button>`:`<button class="btn primary" onclick="toggleLesson('${key}')">Mark section complete</button>`}</div></section>`}).join('')}</div></article></div>`}
function tnaPage(){const vals=DATA.tnaItems.map(item=>state.tna[item]?.level||""),filled=vals.filter(Boolean).length,validated=vals.filter(x=>x==="Previously authorised / validated"||x==="Demonstrated competence").length,gaps=vals.filter(x=>x==="No experience"||x==="Awareness").length;return pageHero("ENTRY / TRAINING NEEDS ANALYSIS","Establish the real starting point.","This is not self-certification. Candidate declarations identify where evidence and review are required; they do not automatically confer competence.")+`<section class="tna-wrap"><div class="container"><div class="tna-summary"><div class="metric"><span class="meta">AREAS COMPLETED</span><strong>${filled} / ${DATA.tnaItems.length}</strong></div><div class="metric"><span class="meta">CLAIMED DEMONSTRATED / VALIDATED</span><strong>${validated}</strong></div><div class="metric"><span class="meta">IDENTIFIED DEVELOPMENT AREAS</span><strong>${gaps}</strong></div></div><div class="tna-table">${DATA.tnaItems.map(item=>{let rec=state.tna[item]||{};return `<div class="tna-row"><strong>${esc(item)}</strong><select onchange="setTna('${esc(item)}','level',this.value)"><option value="">Select level…</option>${DATA.levels.map(l=>`<option ${rec.level===l?'selected':''}>${l}</option>`).join('')}</select><input value="${esc(rec.note||'')}" placeholder="Evidence / comment / previous authorisation…" onchange="setTna('${esc(item)}','note',this.value)"></div>`}).join('')}</div><div class="actions"><button class="btn primary" onclick="saveTna()">Save TNA</button><button class="btn" onclick="goto('#/modules')">View technical modules</button></div></div></section>`}
function governance(){return pageHero("GOVERNANCE & SAFETY","Training supports competence. It does not control live electrical systems.","Powertec Training remains clearly separated from controlled operational instruction.")+`<section class="section"><div class="container prose"><section><h2>Training boundary</h2><p>The platform supports structured learning, competency development, evidence and assessment preparation. It is not a live switching adviser or substitute for Electrical Safety Rules, Approved Procedures, controlled SLDs, switching schedules or authorised instruction.</p></section><section><h2>Site-specific material</h2><p>The core programme is vendor- and site-neutral. Site-specific Safety Rules, architecture, nomenclature, procedures and emergency arrangements should sit in a controlled site module when approved.</p></section><section><h2>Assessment and authorisation</h2><div class="callout"><strong>Assessment readiness ≠ authorisation.</strong><p>Only the applicable organisation and Authorising Engineer can confer authorisation under their governance.</p></div></section></div></section>`}
function architectureLab(){const layers=["HV sources","HV switchboard","Transformers","LV mains & sections","A/B interconnection","UPS & batteries","Bypass / transfer","Critical loads"];return pageHero("ARCHITECTURE LAB","Build a credible SLD progressively.","The system begins simple but retains engineering single-line structure. Complexity is added only after the underlying relationship is understood.")+`<section class="section"><div class="container"><p class="lead">Generic fictional architecture only. It is deliberately not copied from a live site.</p><div class="layer-controls v3">${layers.map((x,i)=>`<button class="on" data-layer="${i}" onclick="toggleSldLayer(this)">${i+1} · ${x}</button>`).join('')}</div><div class="arch-sld"><svg viewBox="0 0 1180 520"><g data-sld="0"><rect class="equip" x="20" y="50" width="105" height="45"/><text x="35" y="77">HV SOURCE A</text><rect class="equip" x="20" y="180" width="105" height="45"/><text x="35" y="207">HV SOURCE B</text><path class="wire" d="M125 72 H180 M125 202 H180"/></g><g data-sld="1"><rect class="equip" x="180" y="25" width="170" height="225"/><text x="205" y="48">22kV SWITCHBOARD</text><path class="bus" d="M205 85 H325 M205 195 H325"/><path class="wire" d="M180 72 H205 V85 M180 202 H205 V195"/><path class="alt" d="M265 85 V195"/><text x="273" y="145">BUS TIE</text></g><g data-sld="2"><path class="wire" d="M325 85 H390 M325 195 H390"/><rect class="equip" x="390" y="50" width="115" height="65"/><text x="420" y="76">TX-A</text><text x="402" y="96">22kV/415V</text><rect class="equip" x="390" y="165" width="115" height="65"/><text x="420" y="191">TX-B</text><text x="402" y="211">22kV/415V</text><path class="wire" d="M505 82 H555 M505 197 H555"/></g><g data-sld="3"><rect class="equip" x="555" y="25" width="225" height="225"/><text x="590" y="48">MAIN LV SWITCHBOARD</text><path class="bus" d="M580 90 H755 M580 195 H755"/><text x="590" y="80">SECTION A</text><text x="590" y="185">SECTION B</text><path class="wire" d="M555 82 H580 V90 M555 197 H580 V195"/><path class="alt" d="M670 90 V195"/><text x="678" y="145">COUPLER</text></g><g data-sld="4"><path class="wire" d="M755 90 H820 V65 H870 M755 195 H820 V220 H870"/><path class="alt" d="M820 65 V220"/><text x="826" y="145">A/B PATH</text></g><g data-sld="5"><rect class="equip" x="870" y="35" width="120" height="75"/><text x="905" y="58">UPS-A</text><text x="884" y="80">RECT-DC-INV</text><rect class="equip" x="870" y="185" width="120" height="75"/><text x="905" y="208">UPS-B</text><text x="884" y="230">RECT-DC-INV</text><rect class="equip" x="875" y="310" width="110" height="40"/><text x="895" y="335">BATTERY A</text><rect class="equip" x="875" y="375" width="110" height="40"/><text x="895" y="400">BATTERY B</text><path class="dc" d="M930 310 V110 M930 375 V260"/></g><g data-sld="6"><path class="alt" d="M820 65 V10 H1030 V72 H990 M820 220 V285 H1030 V222 H990"/><text x="895" y="10">BYPASS PATHS</text><rect class="equip" x="1030" y="45" width="120" height="55"/><text x="1050" y="77">ATS / STS A</text><rect class="equip" x="1030" y="195" width="120" height="55"/><text x="1050" y="227">ATS / STS B</text><path class="wire" d="M990 72 H1030 M990 222 H1030"/></g><g data-sld="7"><rect class="equip" x="1025" y="315" width="130" height="45"/><text x="1050" y="342">IT LOAD A/B</text><rect class="equip" x="1025" y="390" width="130" height="45"/><text x="1045" y="417">AHU / PUMPS</text><path class="wire" d="M1090 250 V315 M1120 250 V390"/></g></svg></div><div class="principle">At each layer the candidate must answer: what can energise the selected equipment now, what changed when this layer appeared, and what information is still missing?</div><div class="assessment-grid"><div class="assess-card"><b>CHECK 1</b><h3>Recognise</h3><p>Identify equipment and system boundaries.</p></div><div class="assess-card"><b>CHECK 2</b><h3>Trace</h3><p>Follow normal, alternate and stored-energy paths.</p></div><div class="assess-card"><b>CHECK 3</b><h3>Change state</h3><p>Hide a layer and explain which assumption changes.</p></div><div class="assess-card"><b>CHECK 4</b><h3>Identify unknowns</h3><p>State what controlled information a real operational decision would require.</p></div></div></div></section>`}function toggleSldLayer(btn){btn.classList.toggle('on');document.querySelectorAll(`[data-sld="${btn.dataset.layer}"]`).forEach(x=>x.classList.toggle('hidden',!btn.classList.contains('on')))}window.toggleSldLayer=toggleSldLayer;
function toggleLesson(key){const i=state.completedLessons.indexOf(key);if(i>=0)state.completedLessons.splice(i,1);else state.completedLessons.push(key);save();render()}
function setTna(item,field,value){if(!state.tna[item])state.tna[item]={};state.tna[item][field]=value}
function saveTna(){save();alert('Training Needs Analysis saved on this device. Candidate declarations remain unvalidated until reviewed by the appropriate mentor/assessor workflow.')}
function toggleLayer(btn){btn.classList.toggle('on');const l=btn.dataset.layer;document.querySelectorAll(`[data-l="${l}"]`).forEach(x=>x.style.display=btn.classList.contains('on')?'':'none')}
window.goto=goto;window.toggleLesson=toggleLesson;window.setTna=setTna;window.saveTna=saveTna;window.toggleLayer=toggleLayer;
function render(){const path=(location.hash||'#/home').slice(2).split('/');let html;switch(path[0]){case'programme':html=programme();break;case'pathways':html=pathways();break;case'modules':html=modulesPage();break;case'module':html=modulePage(path[1]);break;case'tna':html=tnaPage();break;case'governance':html=governance();break;case'lab':html=architectureLab();break;default:html=home()}document.body.classList.toggle('is-home', path[0]==='home' || !path[0]);
document.body.classList.toggle('is-internal', !(path[0]==='home' || !path[0]));
app.innerHTML=html;app.focus({preventScroll:true})}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
